/* @autogenerated */
package net.civeira.phylax.common.crypto;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class ProtectedSecretsUnitTest {
  private static final String PHP_HASH =
      "$argon2id$v=19$m=65536,t=4,p=1$ODROd2QvODZGdmQ2cDVFVQ$XyzMa6pIXFsdSZYRegkuLFd14xMoqQqwDZJ0bCLuPuk";
  private static final String PHP_SEALED =
      "sealed:k1:A8HHyE11QLkxiij9kvfzyr5v92kg45mmOBVrC9aw7TDA7gCivn6O";

  @Test
  void passwordMatchesPhpArgon2id() {
    PasswordHasher hasher = new PasswordHasher();
    assertTrue(hasher.verify("test-secret", PHP_HASH));
    assertFalse(hasher.verify("wrong-secret", PHP_HASH));
    assertFalse(hasher.needsRehash(PHP_HASH));
    assertTrue(hasher.verify("test-secret", hasher.hash("test-secret")));
  }

  @Test
  void digestMatchesPhpHmacAndRotation() {
    SecretDigester digester = new SecretDigester("p1:integration-pepper", "p1");
    String stored =
        "hmac-sha256:p1:a90d1dac6d10b69e9451136927c66431ecedaa4de840cebfacf6bd60e1e80f3e";
    assertEquals(stored, digester.digest("test-secret"));
    assertTrue(digester.verify("test-secret", stored));
    assertFalse(digester.verify("wrong-secret", stored));
    SecretDigester rotated = new SecretDigester("p2:next,p1:integration-pepper", "p2");
    assertTrue(rotated.verify("test-secret", stored));
    assertTrue(rotated.needsRehash(stored));
  }

  @Test
  void encryptedValueOpensPhpEnvelopeOnlyForItsOwner() {
    KeyRingSecretStorage storage = new KeyRingSecretStorage("k1:integration-key", "k1");
    assertEquals("test-secret", storage.open(PHP_SEALED, "access.test.secret#owner-1"));
    assertTrue(
        new KeyRingSecretStorage("k2:next,k1:integration-key", "k2").needsReseal(PHP_SEALED));
    assertThrows(IllegalArgumentException.class,
        () -> storage.open(PHP_SEALED, "access.test.secret#another-owner"));
    assertEquals("test-secret", storage.open(
        storage.seal("test-secret", "access.test.secret#owner-1"), "access.test.secret#owner-1"));
  }
}
